// THE R2 CONTROL: does an UNPATCHED rebuild alone move this lane's labels?
//
// Build A = the parser the upstream package SHIPPED (its committed src/parser.c, built to wasm).
// Build B = the SAME upstream grammar.js regenerated by the fleet CLI tree-sitter 0.26.9.
// Nothing of this lane's patch is in either build. Any label difference between them is the
// cost of the RUNG (parser-version drift), not the cost of the patch.
//
// Both builds are run through the REAL analyzer, one file at a time, over a controlled sample:
// the lane's own fixtures (the constructs the patched grammar targets), the 202-file tail that
// used to hang, and a stride over the rest of the admitted population.
import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";
const ROOT = "<corpus-root>/mcp/backbencher-brain";
const CORPUS = "<corpus-root>/bb_tests/repositories";
const CTL = ROOT + "/script/m14/tmp/groovy-control";
const EXTS = ["groovy", "gvy", "gradle"];
const CAP = 1048576;

const wts = await import(ROOT + "/node_modules/web-tree-sitter/tree-sitter.js");
const Parser = wts.Parser ?? wts.default ?? wts;
const Language = wts.Language ?? wts.default?.Language;
await Parser.init({ locateFile: () => path.join(ROOT, "node_modules/web-tree-sitter/tree-sitter.wasm") });
const langA = await Language.load(CTL + "/control-shipped.wasm");
const langB = await Language.load(CTL + "/control-regen.wasm");
const { RealGroovyAnalyzer } = await import(ROOT + "/src/ast/real-groovy-analyzer.ts");

// ---- the admitted population, in the router's extension order ----
const admitted = [];
for (const r of fs.readdirSync(CORPUS).sort()) {
  const d = path.join(CORPUS, r);
  if (!fs.statSync(d).isDirectory()) continue;
  let files = [];
  try {
    files = execSync(`git -C ${JSON.stringify(d)} ls-files`, { maxBuffer: 1 << 28 }).toString().split("\n");
  } catch {
    continue;
  }
  for (const f of files) {
    if (!f || !EXTS.includes(f.split(".").pop().toLowerCase())) continue;
    const p = path.join(d, f);
    try {
      if (fs.statSync(p).size > CAP) continue;
    } catch {
      continue;
    }
    admitted.push(p);
  }
}
admitted.sort();

// ---- controlled sample: fixtures + former hang tail + stride ----
const fixtures = [];
const fxDir = ROOT + "/validation/m14/fixtures/groovy";
for (const f of fs.readdirSync(fxDir)) if (f.endsWith(".groovy")) fixtures.push(path.join(fxDir, f));
const tail = admitted.slice(7900);
const stride = [];
for (let i = 0; i < admitted.length; i += 47) stride.push(admitted[i]);
const files = [...new Set([...fixtures, ...tail, ...stride])];

// ---- node-type inventory per build, over the sample ----
const inventory = { A: new Set(), B: new Set() };

const canon = (r) => ({
  syms: (r.symbols ?? []).map((s) => `${s.name}|${s.kind}|${s.ownerName ?? ""}|${s.range?.startLine ?? 0}`).sort(),
  rels: (r.relationships ?? []).map((x) => `${x.type}|${x.source}|${x.target}|${x.line_number ?? 0}`).sort(),
});

const labelMoves = new Map(); // label -> {added, removed, files}
let perturbed = [];
let errorsA = 0;
let errorsB = 0;
let parseErrA = 0;
let parseErrB = 0;

for (const f of files) {
  const src = fs.readFileSync(f, "utf8");
  const run = (lang) => {
    const p = new Parser();
    p.setLanguage(lang);
    const tree = p.parse(src);
    // inventory: walk named node types once
    const st = [tree.rootNode];
    while (st.length) {
      const n = st.pop();
      if (n.isNamed) (lang === langA ? inventory.A : inventory.B).add(n.type);
      for (let i = 0; i < n.namedChildCount; i++) st.push(n.namedChild(i));
    }
    const out = new RealGroovyAnalyzer().analyze(tree.rootNode, src, f);
    return { canon: canon(out), hasError: tree.rootNode.hasError };
  };
  let A, B;
  try {
    A = run(langA);
  } catch {
    errorsA++;
    continue;
  }
  try {
    B = run(langB);
  } catch {
    errorsB++;
    continue;
  }
  if (A.hasError) parseErrA++;
  if (B.hasError) parseErrB++;

  const setA = new Set([...A.canon.rels]);
  const setB = new Set([...B.canon.rels]);
  const symA = new Set([...A.canon.syms]);
  const symB = new Set([...B.canon.syms]);
  const added = [...setB].filter((x) => !setA.has(x));
  const removed = [...setA].filter((x) => !setB.has(x));
  const symAdded = [...symB].filter((x) => !symA.has(x));
  const symRemoved = [...symA].filter((x) => !symB.has(x));
  if (added.length || removed.length || symAdded.length || symRemoved.length) {
    perturbed.push({ f: path.relative(CORPUS, f), added, removed, symAdded, symRemoved });
    for (const x of added) {
      const k = "rel+" + x.split("|")[0];
      const e = labelMoves.get(k) ?? { added: 0, removed: 0 };
      e.added++;
      labelMoves.set(k, e);
    }
    for (const x of removed) {
      const k = "rel-" + x.split("|")[0];
      const e = labelMoves.get(k) ?? { added: 0, removed: 0 };
      e.removed++;
      labelMoves.set(k, e);
    }
    if (symAdded.length || symRemoved.length) {
      const e = labelMoves.get("symbols") ?? { added: 0, removed: 0 };
      e.added += symAdded.length;
      e.removed += symRemoved.length;
      labelMoves.set("symbols", e);
    }
  }
}

const onlyA = [...inventory.A].filter((t) => !inventory.B.has(t));
const onlyB = [...inventory.B].filter((t) => !inventory.A.has(t));
console.log("=== R2 CONTROL: unpatched rebuild (CLI 0.26.9) vs the parser upstream shipped ===");
console.log(`sample files: ${files.length}  (fixtures ${fixtures.length}, former-hang tail ${tail.length}, stride ${stride.length}, union ${files.length})`);
console.log(`files perturbed: ${perturbed.length} / ${files.length}`);
console.log(`parse-error files: shipped ${parseErrA} · regenerated ${parseErrB}`);
console.log(`analyzer exceptions: shipped ${errorsA} · regenerated ${errorsB}`);
console.log(`node types seen: shipped ${inventory.A.size} · regenerated ${inventory.B.size} · only-shipped ${onlyA.length} · only-regenerated ${onlyB.length}`);
if (onlyA.length) console.log("  only in shipped  :", onlyA.slice(0, 12).join(", "));
if (onlyB.length) console.log("  only in regenerated:", onlyB.slice(0, 12).join(", "));
console.log("--- label movements (regenerated minus shipped) ---");
const rows = [...labelMoves.entries()].sort((a, b) => b[1].added + b[1].removed - (a[1].added + a[1].removed));
if (!rows.length) console.log("  NONE — no label moved on any sampled file");
for (const [k, v] of rows) console.log(`  ${k.padEnd(28)} +${v.added}  -${v.removed}`);
const top = perturbed.slice(0, 6);
for (const p of top) {
  console.log(`  eg ${p.f}: +${p.added.length} -${p.removed.length} rel, +${p.symAdded.length} -${p.symRemoved.length} sym`);
  for (const x of p.removed.slice(0, 2)) console.log(`       removed ${x}`);
  for (const x of p.added.slice(0, 2)) console.log(`       added   ${x}`);
}
